record.field:
{"type": "object", "properties": {"product_name": {"type": "string",
            "description": "Finished product name (or internal reference), e.g. 'PVC板'"}},
            "required": ["product_name"]}

if 'mrp.bom' not in env:
    ai['result'] = "ERROR: the Manufacturing app (mrp) is not installed in this database."
else:
    base = (product_name or '').replace('（', '(').replace('）', ')').split('(')[0].strip()
    tmpl = env['product.template'].search([['name', '=ilike', base]], limit=1)
    if not tmpl:
        hits = env['product.template'].search([['name', 'ilike', base]], limit=5)
        if len(hits) == 1:
            tmpl = hits
        elif hits:
            names = "; ".join(f"ID {t.id}: {t.display_name}" for t in hits)
            ai['result'] = f"ERROR: several products match '{base}': {names}. Ask the user which one."
        else:
            ai['result'] = f"ERROR: product '{base}' not found."
    if tmpl and 'result' not in ai:
        boms = env['mrp.bom'].search([['product_tmpl_id', '=', tmpl.id]], limit=5)
        if not boms:
            ai['result'] = (
                f"No BOM exists for '{tmpl.display_name}'. "
                "Create one with 'AI MRP: Create BOM' (components must already exist as products)."
            )
        else:
            blocks = []
            for bom in boms:
                target = bom.product_id.display_name if bom.product_id else f"{tmpl.display_name} (all variants)"
                btype = "Kit (phantom)" if bom.type == 'phantom' else "Manufacture this product"
                head = (
                    f"BOM ID {bom.id}" + (f" [{bom.code}]" if bom.code else "") + f" — {target}\n"
                    f"  Makes: {bom.product_qty} {bom.product_uom_id.name} | Type: {btype} | "
                    f"{len(bom.bom_line_ids)} component line(s)"
                )
                lines = []
                for line in bom.bom_line_ids:
                    sub = env['mrp.bom'].search_count(
                        [['product_tmpl_id', '=', line.product_id.product_tmpl_id.id]])
                    applies = ""
                    if line.bom_product_template_attribute_value_ids:
                        applies = " [only for variant: " + ", ".join(
                            line.bom_product_template_attribute_value_ids.mapped('name')) + "]"
                    lines.append(
                        f"    - {line.product_id.display_name}: {line.product_qty} "
                        f"{line.product_uom_id.name}"
                        + (" (has sub-BOM)" if sub else "") + applies
                    )
                blocks.append(head + "\n" + "\n".join(lines))
            ai['result'] = "\n\n".join(blocks)

if 'mrp.bom' not in env:
    ai['result'] = "ERROR: the Manufacturing app (mrp) is not installed in this database."
else:
    norm = (product_name or '').replace('（', '(').replace('）', ')').strip()
    base = norm.split('(')[0].strip() if '(' in norm else norm
    inner = norm.split('(', 1)[1].split(')')[0] if '(' in norm else ''
    for sep in ('，', '、', '|', '；', ';'):
        inner = inner.replace(sep, ',')
    wanted = [w.strip().lower() for w in inner.split(',') if w.strip()]
    tmpl = env['product.template'].search([['name', '=ilike', base]], limit=1)
    if not tmpl:
        hits = env['product.template'].search([['name', 'ilike', base]], limit=5)
        tmpl = hits if len(hits) == 1 else tmpl
        if not tmpl:
            ai['result'] = f"ERROR: product '{base}' not found."
    if tmpl and 'result' not in ai:
        variant = env['product.product']
        if wanted:
            matched = env['product.product']
            loose = env['product.product']
            for p in tmpl.product_variant_ids:
                vname_list = [(n or '').lower() for n in p.product_template_attribute_value_ids.mapped('name')]
                exact_ok = True
                loose_ok = True
                for w in wanted:
                    if w not in vname_list:
                        exact_ok = False
                    hit = False
                    for n in vname_list:
                        if w in n:
                            hit = True
                            break
                    if not hit:
                        loose_ok = False
                if exact_ok:
                    matched += p
                if loose_ok:
                    loose += p
            cand = matched if matched else loose
            if len(cand) == 1:
                variant = cand
            else:
                names = "; ".join(f"ID {p.id}: {p.display_name}" for p in tmpl.product_variant_ids[:12])
                ai['result'] = (
                    f"ERROR: '{product_name}' does not select exactly one variant. Variants: {names}. "
                    "Ask the user which one (quick options)."
                )
    if tmpl and 'result' not in ai:
        try:
            qty = float(quantity) if str(quantity).strip() else 1.0
        except (ValueError, TypeError):
            qty = 1.0
        bom = env['mrp.bom']
        if variant:
            bom = env['mrp.bom'].search([['product_id', '=', variant.id]], limit=1)
        if not bom:
            bom = env['mrp.bom'].search(
                [['product_tmpl_id', '=', tmpl.id], ['product_id', '=', False]], limit=1)
        if not bom:
            bom = env['mrp.bom'].search([['product_tmpl_id', '=', tmpl.id]], limit=1)
        if not bom:
            ai['result'] = (
                f"ERROR: no BOM exists for '{tmpl.display_name}'. "
                "Create one first with 'AI MRP: Create BOM'."
            )
        else:
            factor = qty / bom.product_qty if bom.product_qty else qty
            rows = []
            shortages = 0
            for line in bom.bom_line_ids:
                if variant and line.bom_product_template_attribute_value_ids and (
                        line.bom_product_template_attribute_value_ids
                        - variant.product_template_attribute_value_ids):
                    continue
                comp = line.product_id
                required = line.product_qty * factor
                free = comp.free_qty
                onhand = comp.qty_available
                unit_note = ""
                if line.product_uom_id != comp.uom_id:
                    unit_note = (
                        f" [required in {line.product_uom_id.name}, stock in {comp.uom_id.name}"
                        " — different units, verify conversion manually]"
                    )
                if required > free:
                    shortages += 1
                    rows.append(
                        f"  - SHORT {comp.display_name}: need {required}, free {free} "
                        f"(on hand {onhand}) — missing {required - free}{unit_note}"
                    )
                else:
                    rows.append(
                        f"  - OK    {comp.display_name}: need {required}, free {free} "
                        f"(on hand {onhand}){unit_note}"
                    )
            target_name = variant.display_name if variant else tmpl.display_name
            head = (
                f"Component check for {qty} x {target_name} "
                f"(BOM ID {bom.id}, makes {bom.product_qty} {bom.product_uom_id.name} per run):"
            )
            if shortages:
                tail = (
                    f"\n{shortages} component(s) SHORT. Options: purchase/manufacture the missing "
                    "components first, or reduce the quantity. Do NOT force production through a shortage."
                )
            else:
                tail = "\nAll components available."
            ai['result'] = head + "\n" + "\n".join(rows) + tail

if 'mrp.production' not in env:
    ai['result'] = "ERROR: the Manufacturing app (mrp) is not installed in this database."
else:
    domain = []
    if (mo_name or '').strip():
        domain.append(['name', 'ilike', mo_name.strip()])
    if (product_name or '').strip():
        domain.append(['product_id.name', 'ilike', product_name.strip()])
    valid_states = ('draft', 'confirmed', 'progress', 'to_close', 'done', 'cancel')
    if (state or '').strip():
        if state.strip() in valid_states:
            domain.append(['state', '=', state.strip()])
        else:
            ai['result'] = f"ERROR: invalid state '{state}'. Valid: {', '.join(valid_states)}."
    if 'result' not in ai:
        if not domain:
            ai['result'] = "ERROR: provide at least one criterion (mo_name, product_name or state)."
        else:
            orders = env['mrp.production'].search(domain, limit=10, order='id desc')
            if not orders:
                ai['result'] = "No manufacturing orders found matching the criteria."
            else:
                lines = ["Found manufacturing orders:"]
                for mo in orders:
                    avail = mo.components_availability or mo.reservation_state or '-'
                    lines.append(
                        f"  {mo.name} | {mo.product_id.display_name} | qty={mo.product_qty} "
                        f"{mo.product_uom_id.name} | state={mo.state} | components={avail} | "
                        f"start={mo.date_start or '-'}"
                    )
                ai['result'] = "\n".join(lines)

if 'mrp.bom' not in env:
    ai['result'] = "ERROR: the Manufacturing app (mrp) is not installed in this database."
else:
    comp_names = component_names or []
    comp_qtys = component_qtys or []
    if len(comp_names) != len(comp_qtys):
        ai['result'] = "ERROR: component_names and component_qtys must be parallel arrays of the same length."
    elif not comp_names:
        ai['result'] = "ERROR: at least one component is required to build a BOM."
    else:
        norm = (product_name or '').replace('（', '(').replace('）', ')').strip()
        base = norm.split('(')[0].strip() if '(' in norm else norm
        inner = norm.split('(', 1)[1].split(')')[0] if '(' in norm else ''
        for sep in ('，', '、', '|', '；', ';'):
            inner = inner.replace(sep, ',')
        wanted = [w.strip().lower() for w in inner.split(',') if w.strip()]
        tmpl = env['product.template'].search([['name', '=ilike', base]], limit=1)
        if not tmpl:
            hits = env['product.template'].search([['name', 'ilike', base]], limit=5)
            if len(hits) == 1:
                tmpl = hits
            elif hits:
                names = "; ".join(f"ID {t.id}: {t.display_name}" for t in hits)
                ai['result'] = f"ERROR: several products match '{base}': {names}. Ask the user which one (quick options)."
            else:
                ai['result'] = (
                    f"ERROR: finished product '{base}' not found. Create the product first "
                    "(AI Skill: Create Record, then Configure Product Variants if it has attributes), then retry."
                )
        variant = env['product.product']
        if tmpl and 'result' not in ai and wanted:
            matched = env['product.product']
            loose = env['product.product']
            for p in tmpl.product_variant_ids:
                vname_list = [(n or '').lower() for n in p.product_template_attribute_value_ids.mapped('name')]
                exact_ok = True
                loose_ok = True
                for w in wanted:
                    if w not in vname_list:
                        exact_ok = False
                    hit = False
                    for n in vname_list:
                        if w in n:
                            hit = True
                            break
                    if not hit:
                        loose_ok = False
                if exact_ok:
                    matched += p
                if loose_ok:
                    loose += p
            cand = matched if matched else loose
            if len(cand) == 1:
                variant = cand
            else:
                names = "; ".join(f"ID {p.id}: {p.display_name}" for p in tmpl.product_variant_ids[:12])
                ai['result'] = (
                    f"ERROR: '{product_name}' does not select exactly one variant for a variant-specific BOM. "
                    f"Variants: {names}. Ask the user which one, or use the plain product name for a BOM "
                    "covering all variants."
                )
        if tmpl and 'result' not in ai:
            existing = env['mrp.bom'].search([['product_tmpl_id', '=', tmpl.id]], limit=3)
            wants_update = str(update_existing).strip().lower() in ('true', '1', 'yes')
            if existing and not wants_update:
                rows = []
                for b in existing:
                    who = b.product_id.display_name if b.product_id else f"{tmpl.display_name} (all variants)"
                    rows.append(
                        f"  - BOM ID {b.id}" + (f" [{b.code}]" if b.code else "")
                        + f" for {who}: makes {b.product_qty} {b.product_uom_id.name}, "
                        + f"{len(b.bom_line_ids)} line(s)"
                    )
                ai['result'] = (
                    "BLOCKED: a BOM already exists for this product:\n" + "\n".join(rows)
                    + "\nAsk the user (quick options): update the existing BOM "
                    "(retry with update_existing='true') or keep it unchanged. Never create a duplicate BOM silently."
                )
            else:
                errors = []
                resolved = []
                for comp_name, comp_qty in zip(comp_names, comp_qtys):
                    cn = (comp_name or '').replace('（', '(').replace('）', ')').strip()
                    cbase = cn.split('(')[0].strip() if '(' in cn else cn
                    cinner = cn.split('(', 1)[1].split(')')[0] if '(' in cn else ''
                    for sep in ('，', '、', '|', '；', ';'):
                        cinner = cinner.replace(sep, ',')
                    cwanted = [w.strip().lower() for w in cinner.split(',') if w.strip()]
                    try:
                        qty_f = float(comp_qty) if str(comp_qty).strip() else 1.0
                    except (ValueError, TypeError):
                        errors.append(f"'{comp_name}': invalid quantity '{comp_qty}'.")
                        continue
                    if not qty_f > 0:
                        errors.append(f"'{comp_name}': quantity must be positive (got {qty_f}).")
                        continue
                    comp = env['product.product'].search([['default_code', '=ilike', cbase]], limit=1)
                    if not comp:
                        ctmpl = env['product.template'].search([['name', '=ilike', cbase]], limit=1)
                        if not ctmpl:
                            chits = env['product.template'].search([['name', 'ilike', cbase]], limit=5)
                            if len(chits) == 1:
                                ctmpl = chits
                            elif chits:
                                names = "; ".join(f"ID {t.id}: {t.display_name}" for t in chits)
                                errors.append(f"'{comp_name}': several products match — {names}. Ask the user which one.")
                                continue
                        if not ctmpl:
                            errors.append(
                                f"'{comp_name}': product not found. Components must exist BEFORE building "
                                "the BOM — create the product first (never invent components)."
                            )
                            continue
                        ccand = ctmpl.product_variant_ids
                        if cwanted:
                            cmatched = env['product.product']
                            cloose = env['product.product']
                            for p in ccand:
                                vname_list = [(n or '').lower() for n in p.product_template_attribute_value_ids.mapped('name')]
                                exact_ok = True
                                loose_ok = True
                                for w in cwanted:
                                    if w not in vname_list:
                                        exact_ok = False
                                    hit = False
                                    for n in vname_list:
                                        if w in n:
                                            hit = True
                                            break
                                    if not hit:
                                        loose_ok = False
                                if exact_ok:
                                    cmatched += p
                                if loose_ok:
                                    cloose += p
                            ccand = cmatched if cmatched else cloose
                        if len(ccand) == 1:
                            comp = ccand
                        elif len(ccand) > 1:
                            names = "; ".join(f"ID {p.id}: {p.display_name}" for p in ccand[:12])
                            errors.append(f"'{comp_name}': several variants match — {names}. Ask the user which one.")
                            continue
                        else:
                            avail = "; ".join(f"ID {p.id}: {p.display_name}" for p in ctmpl.product_variant_ids[:12])
                            errors.append(
                                f"'{comp_name}': no variant matches ({cinner}). Existing variants: {avail}. "
                                "Configure the missing combination first (AI Skill: Configure Product Variants)."
                            )
                            continue
                    if comp.product_tmpl_id.id == tmpl.id:
                        errors.append(f"'{comp_name}': a product cannot be a component of its own BOM.")
                        continue
                    resolved.append((comp, qty_f))
                if errors:
                    ai['result'] = (
                        "ERROR: cannot build the BOM — nothing was created:\n"
                        + "\n".join(f"  - {e}" for e in errors)
                        + "\nFix the issues above and retry (components are never invented or auto-created)."
                    )
                else:
                    try:
                        base_qty = float(bom_qty) if str(bom_qty).strip() else 1.0
                    except (ValueError, TypeError):
                        base_qty = 1.0
                    if not base_qty > 0:
                        base_qty = 1.0
                    btype = 'phantom' if str(bom_type).strip().lower() in ('phantom', 'kit') else 'normal'
                    if existing and wants_update:
                        bom = existing[0]
                        changes = []
                        for comp, qty_f in resolved:
                            line = bom.bom_line_ids.filtered(lambda l: l.product_id == comp)
                            if line:
                                if line[0].product_qty != qty_f:
                                    changes.append(
                                        f"{comp.display_name}: qty {line[0].product_qty} -> {qty_f}")
                                    line[0].write({'product_qty': qty_f})
                            else:
                                env['mrp.bom.line'].create(
                                    {'bom_id': bom.id, 'product_id': comp.id, 'product_qty': qty_f})
                                changes.append(f"added {comp.display_name} x {qty_f}")
                        ai['result'] = (
                            f"BOM updated (ID {bom.id}) for {tmpl.display_name}.\n"
                            + ("\n".join(f"  - {c}" for c in changes) if changes else "  (no changes needed)")
                            + f"\nThe BOM now has {len(bom.bom_line_ids)} component line(s); "
                            "existing lines not mentioned were kept unchanged."
                        )
                    else:
                        line_cmds = [(0, 0, {'product_id': comp.id, 'product_qty': qty_f})
                                     for comp, qty_f in resolved]
                        vals = {
                            'product_tmpl_id': tmpl.id,
                            'product_qty': base_qty,
                            'type': btype,
                            'bom_line_ids': line_cmds,
                        }
                        if variant:
                            vals['product_id'] = variant.id
                        if (code or '').strip():
                            vals['code'] = code.strip()
                        bom = env['mrp.bom'].create(vals)
                        lines_txt = "\n".join(
                            f"  - {comp.display_name}: {qty_f} {comp.uom_id.name}"
                            for comp, qty_f in resolved)
                        target_name = variant.display_name if variant else f"{tmpl.display_name} (all variants)"
                        ai['result'] = (
                            f"BOM created successfully (ID: {bom.id}).\n"
                            f"  Product: {target_name}\n"
                            f"  Makes  : {base_qty} {tmpl.uom_id.name} per run\n"
                            f"  Type   : {'Kit (phantom)' if btype == 'phantom' else 'Manufacture this product'}\n"
                            + (f"  Code   : {code.strip()}\n" if (code or '').strip() else "")
                            + f"Components:\n{lines_txt}\n"
                            "Next: 'AI MRP: Check Component Availability' to verify stock, then "
                            "'AI MRP: Create Manufacturing Order' to produce."
                        )

{"type": "object", "properties": {
            "product_name": {"type": "string", "description": "Product to manufacture, variant syntax supported: 'PVC板(昆明,8mm)'"},
            "quantity": {"type": "string", "description": "Quantity to produce, e.g. '10'"},
            "planned_date": {"type": "string", "description": "Planned start 'YYYY-MM-DD' (or with time 'YYYY-MM-DD HH:MM:SS'). Empty string for now."}},
            "required": ["product_name", "quantity", "planned_date"]}

if 'mrp.production' not in env:
    ai['result'] = "ERROR: the Manufacturing app (mrp) is not installed in this database."
else:
    norm = (product_name or '').replace('（', '(').replace('）', ')').strip()
    base = norm.split('(')[0].strip() if '(' in norm else norm
    inner = norm.split('(', 1)[1].split(')')[0] if '(' in norm else ''
    for sep in ('，', '、', '|', '；', ';'):
        inner = inner.replace(sep, ',')
    wanted = [w.strip().lower() for w in inner.split(',') if w.strip()]
    tmpl = env['product.template'].search([['name', '=ilike', base]], limit=1)
    if not tmpl:
        hits = env['product.template'].search([['name', 'ilike', base]], limit=5)
        if len(hits) == 1:
            tmpl = hits
        elif hits:
            names = "; ".join(f"ID {t.id}: {t.display_name}" for t in hits)
            ai['result'] = f"ERROR: several products match '{base}': {names}. Ask the user which one."
        else:
            ai['result'] = f"ERROR: product '{base}' not found."
    if tmpl and 'result' not in ai:
        variants = tmpl.product_variant_ids
        variant = env['product.product']
        if wanted:
            matched = env['product.product']
            loose = env['product.product']
            for p in variants:
                vname_list = [(n or '').lower() for n in p.product_template_attribute_value_ids.mapped('name')]
                exact_ok = True
                loose_ok = True
                for w in wanted:
                    if w not in vname_list:
                        exact_ok = False
                    hit = False
                    for n in vname_list:
                        if w in n:
                            hit = True
                            break
                    if not hit:
                        loose_ok = False
                if exact_ok:
                    matched += p
                if loose_ok:
                    loose += p
            cand = matched if matched else loose
            if len(cand) == 1:
                variant = cand
        elif len(variants) == 1:
            variant = variants
        if not variant:
            names = "; ".join(f"ID {p.id}: {p.display_name}" for p in variants[:12])
            ai['result'] = (
                f"ERROR: '{product_name}' does not select exactly one variant. Variants: {names}. "
                "A manufacturing order always produces ONE exact variant — ask the user which one (quick options)."
            )
        else:
            try:
                qty = float(quantity) if str(quantity).strip() else 0.0
            except (ValueError, TypeError):
                qty = 0.0
            if not qty > 0:
                ai['result'] = f"ERROR: quantity must be a positive number (got '{quantity}')."
            else:
                bom = env['mrp.bom'].search([['product_id', '=', variant.id]], limit=1)
                if not bom:
                    bom = env['mrp.bom'].search(
                        [['product_tmpl_id', '=', tmpl.id], ['product_id', '=', False]], limit=1)
                if not bom:
                    ai['result'] = (
                        f"ERROR: no BOM exists for '{variant.display_name}'. "
                        "Create one first with 'AI MRP: Create BOM' — a manufacturing order without "
                        "a BOM has no component list."
                    )
                else:
                    vals = {'product_id': variant.id, 'product_qty': qty, 'bom_id': bom.id}
                    if (planned_date or '').strip():
                        vals['date_start'] = planned_date.strip()
                    mo = env['mrp.production'].create(vals)
                    ai['result'] = (
                        f"Manufacturing order created (DRAFT).\n"
                        f"  Reference: {mo.name}\n"
                        f"  ID       : {mo.id}\n"
                        f"  Product  : {mo.product_id.display_name}\n"
                        f"  Quantity : {mo.product_qty} {mo.product_uom_id.name}\n"
                        f"  BOM      : ID {bom.id}" + (f" [{bom.code}]" if bom.code else "") + "\n"
                        f"  Start    : {mo.date_start or '-'}\n"
                        "Next: 'AI MRP: Confirm Manufacturing Order' to confirm and reserve components "
                        "(separate user confirmation required)."
                    )

{"type": "object", "properties": {"mo_name": {"type": "string",
            "description": "Exact MO reference, e.g. WH/MO/00007 (use 'AI MRP: Search Manufacturing Orders' if unsure)"}},
            "required": ["mo_name"]}

if 'mrp.production' not in env:
    ai['result'] = "ERROR: the Manufacturing app (mrp) is not installed in this database."
else:
    mo = env['mrp.production'].search([['name', '=', (mo_name or '').strip()]], limit=1)
    if not mo:
        ai['result'] = f"ERROR: manufacturing order '{mo_name}' not found. Search first to get the exact reference."
    elif mo.state != 'draft':
        ai['result'] = (
            f"ERROR: {mo.name} is in state '{mo.state}' — only DRAFT orders can be confirmed. "
            "Nothing was changed."
        )
    else:
        try:
            mo.action_confirm()
            reserve_note = ""
            try:
                mo.action_assign()
                reserve_note = f"\n  Components: {mo.components_availability or mo.reservation_state or 'see order'}"
            except Exception as reserve_error:
                reserve_note = f"\n  Component reservation issue: {reserve_error}"
            ai['result'] = (
                f"Manufacturing order confirmed.\n"
                f"  Reference: {mo.name}\n"
                f"  State    : {mo.state}"
                + reserve_note + "\n"
                "If components are missing, purchase/produce them first — do not force completion."
            )
        except Exception as e:
            ai['result'] = f"ERROR confirming {mo.name}: {e}"

