        ai['result'] = f"ERROR: manufacturing order '{mo_name}' not found."
    elif mo.state == 'done':
        ai['result'] = f"{mo.name} is already DONE — nothing to do."
    elif mo.state == 'cancel':
        ai['result'] = f"ERROR: {mo.name} is cancelled and cannot be completed."
